import { acquireStartLock, releaseReadyStartLock } from '../serverHandshake';
import { waitForServerShutdown } from '../serverShutdown';
import { errorResult, okResult, type CliCommandResult } from '../envelope';
import { invalidateAttachCache, inspectServer, requestServer } from '../client';
import {
  isCommandResult,
  parseCommandContext,
  serverErrorResult,
  serverUnavailableResult,
  transportErrorResult,
  type AttachUnavailableReason,
} from './shared';

const COMMAND = 'stop';

const stoppedServerUnavailableResult = (
  projectPath: string,
  reason: AttachUnavailableReason,
): CliCommandResult => {
  switch (reason) {
    case 'health_check_failed':
    case 'server_starting':
      return serverUnavailableResult({
        command: COMMAND,
        projectPath,
        reason,
      });
    case 'handshake_invalid':
      return errorResult(
        COMMAND,
        'SERVER_UNAVAILABLE',
        `Rivet's server registration for ${projectPath} is invalid, so the running process cannot be identified or stopped.`,
        { serverUnavailableReason: reason },
        { isRecoverable: false },
      );
    case 'handshake_missing':
    case 'process_not_running':
      return errorResult(
        COMMAND,
        'SERVER_UNAVAILABLE',
        `Nothing is running for ${projectPath}; there is no Rivet server to stop.`,
        { serverUnavailableReason: reason },
        { isRecoverable: false },
      );
  }
};

export const handleStop = async (args: string[]): Promise<CliCommandResult> => {
  const context = parseCommandContext(COMMAND, args);
  if (isCommandResult(context)) {
    return context;
  }

  let lock = await acquireStartLock(context.projectPath);
  if (!lock) {
    invalidateAttachCache();
    const ready = await inspectServer(context.projectPath);
    if (ready.status === 'attached')
      await releaseReadyStartLock(
        context.projectPath,
        ready.server.handshake.pid,
      );
    lock = await acquireStartLock(context.projectPath);
  }
  if (!lock)
    return errorResult(
      COMMAND,
      'SERVER_UNAVAILABLE',
      'Another Rivet invocation is changing this project runtime. Retry after it finishes.',
      { serverUnavailableReason: 'server_starting' },
      { isRecoverable: true },
    );
  let shouldReleaseLock = true;
  try {
    invalidateAttachCache();
    const availability = await inspectServer(context.projectPath);
    if (availability.status === 'unavailable') {
      return stoppedServerUnavailableResult(
        context.projectPath,
        availability.reason,
      );
    }
    const { server: attached } = availability;

    const response = await requestServer<{ reason?: string; error?: string }>(
      attached,
      '/api/cli/shutdown',
      { method: 'POST', body: {} },
    );
    if (response.status === 409) {
      return errorResult(
        COMMAND,
        'OPERATION_FAILED',
        response.body.error ??
          'This session is host-managed; stop it from the agent that opened it.',
        response.body,
      );
    }
    if (response.status !== 200) {
      return serverErrorResult(COMMAND, response.status, response.body);
    }
    if (!(await waitForServerShutdown(attached))) {
      await lock.holdForProcess(attached.handshake.pid, 'retiring');
      shouldReleaseLock = false;
      return errorResult(
        COMMAND,
        'SERVER_UNAVAILABLE',
        'Shutdown was accepted but the server has not exited. Retry after it finishes.',
        { serverUnavailableReason: 'server_shutdown_pending' },
        { isRecoverable: true },
      );
    }
    return okResult(COMMAND, {
      stopping: false,
      stopped: true,
      rivetPort: attached.handshake.rivetPort,
    });
  } catch (error) {
    return transportErrorResult(COMMAND, error);
  } finally {
    if (shouldReleaseLock) await lock.release();
  }
};
